using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using CatGunner.Runtime;
public static class SetupUiLayeringPreview
{
 static string Dir=>Path.GetFullPath(Application.dataPath+"/../../../art/ui-layering/20261014");
 public static string Setup(){if(Application.isPlaying)throw new Exception("EditMode required");var c=UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);if(c==null)throw new Exception("GameClient scene required");File.WriteAllText(Dir+"/preview-state.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{c.SaveFolderOverride,c.Persist,dirty=c.gameObject.scene.isDirty,testHost=SessionState.GetString("CatGunner.Recovery.TestHostFolder",string.Empty)}));c.SaveFolderOverride=Path.Combine(Application.temporaryCachePath,"UiLayeringPreview-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss"));c.Persist=false;SessionState.SetString("CatGunner.Recovery.TestHostFolder",c.SaveFolderOverride);AssetDatabase.DisallowAutoRefresh();return c.SaveFolderOverride;}
 public static string Restore(){if(Application.isPlaying)throw new Exception("EditMode required");var c=UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);var s=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(Dir+"/preview-state.json"));c.SaveFolderOverride=s["SaveFolderOverride"].Type==Newtonsoft.Json.Linq.JTokenType.Null?null:(string)s["SaveFolderOverride"];c.Persist=(bool)s["Persist"];SessionState.SetString("CatGunner.Recovery.TestHostFolder",(string)s["testHost"]??string.Empty);AssetDatabase.AllowAutoRefresh();EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(c.gameObject.scene);if(!EditorSceneManager.SaveScene(c.gameObject.scene))throw new Exception("Restore save failed");return "Preview save override restored; authored scene saved";}
}
